export class Base {
    constructor(start) {
        this.value = start;
    }

    next(delta) {
        return this.value + delta;
    }
}

export class Child extends Base {
    constructor(start, bonus) {
        super(start);
        this.bonus = bonus;
    }

    total(delta) {
        return this.next(delta) + this.bonus;
    }
}

export const label = "js-class-extends";
